CREATE UNIQUE INDEX connections_scope_id ON connections(tenant_id,project_id,id);
ALTER TABLE connections ADD COLUMN generation INTEGER NOT NULL DEFAULT 1;
ALTER TABLE documents ADD COLUMN connection_id TEXT REFERENCES connections(id);
UPDATE documents SET connection_id=(SELECT c.id FROM connections c WHERE c.tenant_id=documents.tenant_id AND c.project_id=documents.project_id AND c.provider=documents.provider) WHERE (SELECT count(*) FROM connections c WHERE c.tenant_id=documents.tenant_id AND c.project_id=documents.project_id AND c.provider=documents.provider)=1;
CREATE TABLE integration_profiles(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,version INTEGER NOT NULL,UNIQUE(tenant_id,project_id,id),FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id));
CREATE TABLE profile_versions(profile_id TEXT NOT NULL,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,version INTEGER NOT NULL,configuration TEXT NOT NULL,digest TEXT NOT NULL,requested_by TEXT NOT NULL,status TEXT NOT NULL,approved_by TEXT,created TEXT NOT NULL,PRIMARY KEY(profile_id,version),FOREIGN KEY(tenant_id,project_id,profile_id) REFERENCES integration_profiles(tenant_id,project_id,id));
CREATE TABLE handovers(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,project_id TEXT NOT NULL,profile_id TEXT NOT NULL,profile_version INTEGER NOT NULL,manifest TEXT NOT NULL,digest TEXT NOT NULL,snapshot_digest TEXT NOT NULL,requested_by TEXT NOT NULL,status TEXT NOT NULL,approved_by TEXT,created TEXT NOT NULL,expires INTEGER NOT NULL,FOREIGN KEY(tenant_id,project_id,profile_id) REFERENCES integration_profiles(tenant_id,project_id,id));
